  static Background4KEntry bySlot(int index) {
    final safe = ((index % 500) + 500) % 500;
    return all500[safe];
  }

  /// خلفية السبحة الإسلامية الدورية (تتبدل كل ١٠٠ تسبيحة عبر ٣٠ صورة إسلامية مخصصة)
  static Background4KEntry forTasbihStage(int stageIndex) {
    final safe = ((stageIndex % tasbihIslamic30.length) + tasbihIslamic30.length) %
        tasbihIslamic30.length;
    return tasbihIslamic30[safe];
  }

  /// تخصيص ٢٠ خلفية مختلفة لحقيبة الفردوس (٠..١٩)
  static Background4KEntry forBagItem(int idx) => bySlot(idx.clamp(0, 19));

  /// خلفيات واقعية منفصلة لبطاقات التقويم حسب كل صلاة (٢٠..٢٧)
  static Background4KEntry forCalendarPrayer(String prayerKey) {
    switch (prayerKey.toLowerCase()) {
      case 'fajr':
        return all500[20];
      case 'sunrise':
        return all500[21];
      case 'duha':
        return all500[22];
      case 'dhuhr':
        return all500[23];
      case 'asr':
        return all500[24];
      case 'maghrib':
        return all500[25];
      case 'isha':
        return all500[26];
      default:
        return all500[27];
    }
  }

  /// خلفيات واقعية منفصلة لبطاقات سجل الصلوات التاريخي (٢٨..٣٥)
  static Background4KEntry forPrayerLogKey(String prayerKey) {
    switch (prayerKey.toLowerCase()) {
      case 'fajr':
        return all500[28];
      case 'dhuhr':
        return all500[29];
      case 'asr':
        return all500[30];
      case 'maghrib':
        return all500[31];
      case 'isha':
        return all500[32];
      default:
        return all500[33];
    }
  }

  /// خلفيات منفصلة للواجهة الرئيسية والصلوات والأقسام الصغيرة (٣٦..٦١)
  static Background4KEntry forHomePrayerSlide(int idx) => bySlot(36 + (idx % 8));
  static Background4KEntry forHomeSection(int idx) => bySlot(44 + (idx % 18));

  /// خلفيات منفصلة لأجزاء التقويم والشريط والمناسبات والأيام (٦٢..١٠٩)
  static Background4KEntry forCalendarSection(int idx) => bySlot(62 + (idx % 48));

  /// خلفيات منفصلة للمهام والطاعات والألقاب والمذكرات والأحداث (١١٠..١٦٩)
  static Background4KEntry forMissionItem(int idx) => bySlot(110 + (idx % 40));
  static Background4KEntry forEventItem(int idx) => bySlot(150 + (idx % 20));

  /// خلفيات منفصلة لساحة المسابقات والألعاب والمليونير وتحدي العائلة (١٧٠..٢٦٩)
  static Background4KEntry forArenaSection(int idx) => bySlot(170 + (idx % 20));
  static Background4KEntry forArenaGame(int gameIdx) => bySlot(190 + (gameIdx % 35));
  static Background4KEntry forMillionaireSection(int idx) => bySlot(225 + (idx % 20));
  static Background4KEntry forFamilySection(int idx) => bySlot(245 + (idx % 25));

  /// خلفيات منفصلة لشاشة ساعدني وبنك الـ ٥٠٠ سؤال وبطاقاتها (٢٧٠..٣٢٩)
  static Background4KEntry forHelpMeBanner(int idx) => bySlot(270 + (idx % 10));
  static Background4KEntry forHelpMeCategory(int idx) => bySlot(280 + (idx % 50));

  /// خلفيات منفصلة لكل بطاقات الإعدادات ومكونات التطبيق الأخرى (٣٣٠..٤٩٩)
  static Background4KEntry forSettingsSection(int idx) => bySlot(330 + (idx % 40));
  static Background4KEntry forExtraSection(int idx) => bySlot(370 + (idx % 130));

  static Background4KEntry jannatiByIndex(int index) {
    final safe = ((index % 100) + 100) % 100;
    return jannati100[safe];
  }
